-- PROPOSED — NOT APPLIED. GENERATED by apps/api/src/lib/domain/entity-graph/entity-graph-facts-ddl.js; do not hand-edit.
-- Entity Graph property facts read model (EG9 P0 eg_property_facts + eg_refresh_log).
--
-- One row per property with every value a property grid column shows / sorts / filters on:
--   170 plain columns copied from v_entity_graph_properties (same names, same types)
--   123 computed facts (SMS eligibility + reason, last contact, pipeline / conversation stage + status,
--   known equity, liens vs filings, signals, owning-company registry status, owner / person / contact / ZIP / engine fields)
-- Computed facts are written by the API refresh job (entity-graph-facts-refresh.js) with the SAME JS functions the
-- grid cells render from — this migration creates storage only; it computes nothing.
-- Estimated size (prod 2026-10-09, 0.5% sample): ~1.0 KB plain + ~0.3 KB computed per row × 176.6K ≈ 240 MB heap,
--   + 46 (col, property_id) btrees (~5–8 MB each) + 3 GIN + 4 trigram.
-- Reads: service role only (direct-PG pool). Writes: the refresh job only.
-- Apply via the MCP channel (migration history is broken — memory 09-04); run the pretest first.
--
-- After apply (owner):
--   1. EG_FACTS_REFRESH_ENABLED=true on the API, then POST /api/internal/entity-graph/facts-refresh?mode=full once (cron auth).
--      Entity Graph keeps the live computation until that run logs status 'ok' in eg_refresh_log.
--   2. Worker cron (infra/cloudflare/worker/index.ts, its own flag CRON_EG_FACTS_REFRESH_ENABLED, send-incapable):
--        */5 0-11,15-23 * * *  POST …/facts-refresh?mode=incremental   (skips the 11:15–14:30 UTC heavy-read blackout)
--        30 9 * * *            POST …/facts-refresh?mode=full          (after refresh_entity_graph_read_model, 09:17 UTC)
--   3. Kill switch without dropping anything: EG_FACTS_TABLE_READS=off (reads fall back to the live computation).

create extension if not exists pg_trgm;

create table if not exists public.eg_refresh_log (
  id           bigserial primary key,
  name         text not null,
  mode         text not null check (mode in ('full', 'incremental')),
  status       text not null check (status in ('running', 'ok', 'failed')),
  started_at   timestamptz not null default now(),
  finished_at  timestamptz,
  rows         integer,
  watermark    timestamptz,
  error        text,
  detail       jsonb not null default '{}'::jsonb
);
create index if not exists eg_refresh_log_name_status_idx on public.eg_refresh_log (name, status, finished_at desc);

